<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Proportion Calculator Online','description'=>'Solve proportions quickly using four simple values.','url'=>'https://smarttoolz.in/tools/proportion-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Proportion Calculator</h1><p>Solve A:B = C:X instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>A<input id="a" type="number" value="2"></label><label>B<input id="b" type="number" value="3"></label><label>C<input id="c" type="number" value="10"></label><button id="go" class="tool-btn">Solve X</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let A=+a.value,B=+b.value,C=+c.value;o.textContent=B?`X = ${(B*C/A).toFixed(4)}`:'Cannot divide by zero.'}</script><?php smarttoolz_tool_page_end(); ?>